/bin/zsh -lc "python3 - <<'PY'
import csv,collections as c
r=list(csv.DictReader(open('data/events.csv')))
for k in r[0]:
 s=c.Counter(x[k] for x in r); print(k,len(s),s.most_common(15))
print(min(x['ts'] for x in r),max(x['ts'] for x in r))
for keys in [('day',),('endpoint','client_version'),('endpoint','region'),('plan','endpoint')]:
 d=c.defaultdict(c.Counter)
 for x in r:
  x['day']=x['ts'][:10];d[tuple(x[k] for k in keys)][x['status']]+=1
 for k,v in sorted(d.items()): print(*k,sum(v.values()),dict(v))
PY"

